DROP TABLE if exists "Validacion Seguridad";

CREATE TABLE "Validacion Seguridad" (
    loan_id bigint PRIMARY KEY,
    "Validacion Seguridad_cd_Validacion Seguridad" int4,
    "Causal Rechazo Seguridad_cd_Causal Rechazo Seguridad" int4,
    seguridad_fallida TEXT, -- Observacion Rechazo Seguridad
    observacion_seguridad TEXT, -- Observación Seguridad
    created_at TIMESTAMP,
    updated_at TIMESTAMP NULL
);


COMMENT ON COLUMN "Validacion Seguridad".loan_id IS 'Identificador Unico Prestamo';
COMMENT ON COLUMN "Validacion Seguridad"."Validacion Seguridad_cd_Validacion Seguridad" IS 'Validación Seguridad';
COMMENT ON COLUMN "Validacion Seguridad"."Causal Rechazo Seguridad_cd_Causal Rechazo Seguridad" IS 'Causal Rechazo Seguridad';
COMMENT ON COLUMN "Validacion Seguridad".seguridad_fallida IS 'Observacion Rechazo Seguridad';
COMMENT ON COLUMN "Validacion Seguridad".observacion_seguridad IS 'Observación Seguridad';
COMMENT ON COLUMN "Validacion Seguridad".created_at IS 'Creado en';
COMMENT ON COLUMN "Validacion Seguridad".updated_at IS 'Actualizado en';


